mapper.select:
SELECT BRM_ID as "brmId", BRM_NM as "brmNm", PARENT_BRM_ID as "parentBrmId", BRM_LVL as "brmLvl",
       BRM_PATH as "brmPath", INST_CD as "instCd", BRM_SRC as "brmSrc", USE_YN as "useYn"
  FROM TB_GOV_BRM WHERE BRM_ID = #{brmId}

WITH RECURSIVE SYS (SYS_CD, DEPTH) AS ( SELECT SYS_CD, 0 FROM TB_SYS_INFO WHERE SYS_CD = #{sysCd} UNION ALL SELECT C.SYS_CD, SYS.DEPTH + 1 FROM TB_SYS_INFO C JOIN SYS ON C.P_SYS_CD = SYS.SYS_CD WHERE SYS.DEPTH < 20 )
SELECT O.DM_ID as "dmId", M.DM_NM as "dmNm", M.DM_SYS_CD as "sysCd", S.SYS_NM as "sysNm", O.OBJ_OWNER as "objOwner", O.OBJ_NM as "objNm", O.OBJ_NM_KR as "objNmKr", O.OBJ_DESC as "objDesc", O.SUBJ_AREA_ID as "subjAreaId", COALESCE(O.GOV_SEND_YN, 'N') as "govSendYn", O.TBL_TP as "tblTp", O.OCCR_CYCLE as "occrCycle", O.OPEN_TP as "openTp", O.OPEN_LIMIT_REASON as "openLimitReason", O.OPEN_LIMIT_BASIS as "openLimitBasis", O.OPEN_DATA_LST_NM as "openDataLstNm", COALESCE(P.COL_CNT, 0) as "colCnt", COALESCE(P.PRIV_CNT, 0) as "privColCnt", COALESCE(P.UNENC_CNT, 0) as "unencPrivColCnt" FROM TB_DATA_MODEL_OBJ O JOIN TB_DATA_MODEL M ON M.DM_ID = O.DM_ID AND M.USE_YN = 'Y' AND COALESCE(M.APRV_STATUS, 'APPROVED') = 'APPROVED' LEFT JOIN TB_SYS_INFO S ON S.SYS_CD = M.DM_SYS_CD LEFT JOIN (SELECT PC."dmId", PC."objOwner", PC."objNm", COUNT(*) as COL_CNT, COUNT(*) FILTER (WHERE PC."privYn" = 'Y') as PRIV_CNT, COUNT(*) FILTER (WHERE PC."privYn" = 'Y' AND PC."encrYn" = 'N') as UNENC_CNT FROM ( AND A.DM_ID = #{dmId} ) PC GROUP BY PC."dmId", PC."objOwner", PC."objNm") P ON P."dmId" = O.DM_ID AND P."objOwner" = O.OBJ_OWNER AND P."objNm" = O.OBJ_NM WHERE O.USE_YN = 'Y' AND COALESCE(O.APRV_STATUS, 'APPROVED') = 'APPROVED' AND M.DM_SYS_CD IN (SELECT SYS_CD FROM SYS) AND O.DM_ID = #{dmId} AND O.OBJ_OWNER = #{objOwner} AND O.SUBJ_AREA_ID = #{subjAreaId} AND (O.OBJ_NM ILIKE '%' || #{objNm} || '%' OR O.OBJ_NM_KR ILIKE '%' || #{objNm} || '%') AND COALESCE(O.GOV_SEND_YN, 'N') = #{govSendYn}
AND O.OPEN_TP IS NULL AND O.OPEN_TP = #{openTp}
AND O.TBL_TP = #{tblTp} AND COALESCE(P.PRIV_CNT, 0) > 0 AND COALESCE(P.PRIV_CNT, 0) = 0 AND COALESCE(P.UNENC_CNT, 0) > 0 ORDER BY S.SYS_NM, M.DM_NM, O.OBJ_OWNER, O.OBJ_NM

mapper.update:
UPDATE TB_GOV_META_SEND
   SET STATUS = #{status}, END_DT = to_char(now(), 'YYYYMMDDHH24MISS'),
       SYS_CNT = #{sysCnt}, DB_CNT = #{dbCnt}, TBL_CNT = #{tblCnt}, COL_CNT = #{colCnt},
       ERR_CNT = #{errCnt}, WARN_CNT = #{warnCnt}, SEND_MSG = #{sendMsg, jdbcType=VARCHAR}
 WHERE SEND_ID = #{sendId}
